package com.gameaggregator.deploymentservice.domain;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity @Table(name="deployment_events") public class DeploymentEvent{@Id public UUID id=UUID.randomUUID();@Column(nullable=false)public UUID deploymentId;@Enumerated(EnumType.STRING)@Column(nullable=false)public DeploymentStatus fromStatus;@Enumerated(EnumType.STRING)@Column(nullable=false)public DeploymentStatus toStatus;@Column(nullable=false)public UUID actorId;public String message;@Column(nullable=false)public Instant createdAt=Instant.now();protected DeploymentEvent(){}public DeploymentEvent(UUID d,DeploymentStatus f,DeploymentStatus t,UUID a,String m){deploymentId=d;fromStatus=f;toStatus=t;actorId=a;message=m;}}